function house(a,r){let g=new T.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);g.rotation.y=-a+Math.PI/2;scene.add(g);for(const x of [-3,3])for(const z of [-2,2])box(.3,3,.3,wood,x,1,z,g);box(7,.4,5,gold,0,2.5,0,g);box(6,3.5,4,wood,0,4.3,0,g);for(const x of [-2,0,2])box(.85,1.4,.06,glow,x,4.3,2.03,g);for(const side of [-1,1]){let q=box(4.6,.25,6,roof,side*1.85,6.8,0,g);q.rotation.z=side*-.6;let p=box(2.7,.08,3.8,solar,side*1.7,7.05,0,g);p.rotation.z=side*-.6;for(let k=0;k<6;k++){let rail=box(.06,.08,4, gold,side*1.7+(k-2.5)*.36,7.12-(side*(k-2.5)*.36)*.68,0,g)}}box(.16,.16,7,gold,0,8,0,g);for(let j=0;j<7;j++)box(7,.16,.3,gold,0,.4+j*.32,4.7-j*.32,g);for(let j=-3;j<=3;j++)box(.1,1,.1,gold,j,3.15,2.5,g);register(g,'house');}
function palm(a,r,s=1){let g=new T.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);g.scale.setScalar(s);scene.add(g);mesh(new T.CylinderGeometry(.24,.55,10,7),wood,0,5,0,g);for(let j=0;j<7;j++){let f=new T.Group();f.position.y=10;f.rotation.y=j*Math.PI*2/7;g.add(f);for(let k=0;k<4;k++){let l=ball(1,leaf,0,-k*k*.18,1+k*1.15,f);l.scale.set(.75,.16,1.7);l.rotation.x=.1+k*.13}fronds.push(f)}ball(.7,dark,0,9.8,0,g)}
for(let i=0;i<28;i++){let a=i/28*Math.PI*2;house(a,110+(i%3)*4);palm(a+.07,102,.8+rnd()*.6);palm(a+.04,76,.7+rnd()*.7)}
for(let i=0;i<100;i++){let a=i/100*Math.PI*2,r=97;let g=new T.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);scene.add(g);box(.12,3,.12,wood,0,1.5,0,g);let l=mesh(new T.OctahedronGeometry(.65),glow,0,3.3,0,g);let wire=mesh(new T.OctahedronGeometry(.7),new T.MeshBasicMaterial({color:'#687043',wireframe:true}),0,3.3,0,g);lamps.push(l);register(g,'lantern');}
