function initAudio(){if(ctx)return;ctx=new AudioContext();analyser=ctx.createAnalyser();analyser.fftSize=256;buffer=new Uint8Array(analyser.frequencyBinCount);master=ctx.createGain();master.gain.value=.35;analyser.connect(master);master.connect(ctx.destination);timer=setInterval(()=>{if(mode==='ambient'&&entered&&!paused){const notes=[220,277.18,329.63,440,369.99,329.63,277.18,440];tone(notes[step++%8],.12,1.8);if(step%4===0)tone(65,.2,.65)}},450)}
