$('mute').onclick=()=>{initAudio();muted=!muted;master.gain.value=muted?0:.35;$('mute').textContent=muted?'◌':'♫';$('mute').setAttribute('aria-label',muted?'Unmute audio':'Mute audio')};$('play').onclick=()=>{paused=!paused;$('play').textContent=paused?'▶':'Ⅱ';$('play').setAttribute('aria-label',paused?'Resume journey':'Pause journey');if(audio){if(paused)audio.pause();else audio.play().catch(()=>{})}};$('day').onclick=()=>{dusk=!dusk;scene.background.set(dusk?'#34495b':'#91bca5');scene.fog.color.copy(scene.background);sun.intensity=dusk?.7:3.1;$('day').textContent=dusk?'☾':'☼'};
const stories={house:['RUMAH · A HOME FOR TOMORROW','Old wisdom. New energy.','Raised timber homes and steep roofs inspire this imagined kampung. Here, solar roofs and planted verandas form a possible future. Tap another home to add a note.'],lantern:['ANYAMAN · INTERLACED LIGHT','A little light, woven together.','These geometric lanterns imagine woven forms as living light. Your tap rings a synthetic chime; the surrounding lights answer the low frequencies in your sound.'],garden:['KEBUN · THE LIVING GARDEN','Let the garden answer.','A speculative tropical garden that blooms when you touch it. Higher frequencies stir the canopy; sound energy gently changes your pace.'],about:['SERI · FIELD NOTES','A future rooted in place.','An endless, interactive Malay-inspired solarpunk reverie. Drag to look; tap houses, woven lanterns, and roadside flowers. Use the microphone or your own music. Audio stays in your browser. This is an imagined world with original synthesized sound, not an archival recording or a reconstruction of a specific village.']};function show(type){const s=stories[type];$('cardTag').textContent=s[0];$('cardTitle').textContent=s[1];$('cardText').textContent=s[2];$('card').hidden=false}$('about').onclick=$('help').onclick=()=>show('about');$('closeCard').onclick=()=>$('card').hidden=true;$('home').onclick=e=>{e.preventDefault();$('intro').hidden=false;$('journey').hidden=true;entered=false;document.body.classList.remove('entered')};
let down=null;renderer.domElement.onpointerdown=e=>{down={x:e.clientX,y:e.clientY,l:look,p:pitch};renderer.domElement.setPointerCapture(e.pointerId)};renderer.domElement.onpointermove=e=>{if(down){look=down.l-(e.clientX-down.x)*.004;pitch=T.MathUtils.clamp(down.p+(e.clientY-down.y)*.002,-.45,.45)}};renderer.domElement.onpointerup=async e=>{if(!down)return;let dist=Math.hypot(e.clientX-down.x,e.clientY-down.y);down=null;if(dist>8)return;if(!entered)await enter();const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2),camera);const hits=ray.intersectObjects(interactive);if(hits.length){let g=hits[0].object.userData.root,type=g.userData.type;show(type);burst=1;g.scale.setScalar(g.scale.x>1?1:1.18);tone(type==='house'?220:type==='lantern'?660:440,.25,2)}};renderer.domElement.onpointercancel=()=>down=null;
