let last=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-last)/1000,.05);last=now;if(analyser){analyser.getByteFrequencyData(buffer);const avg=(a,b)=>buffer.slice(a,b).reduce((s,v)=>s+v,0)/(b-a)/255;bass+=(avg(0,8)-bass)*.1;energy+=(avg(0,64)-energy)*.12;high+=(avg(25,100)-high)*.1}if(!paused)angle+=dt*(entered?.022+energy*.045:.006);burst=Math.max(0,burst-dt*.5);let a=angle;camera.position.set(Math.cos(a)*R,entered?3.4:8,Math.sin(a)*R);let forward=new T.Vector3(-Math.sin(a),pitch,Math.cos(a));forward.applyAxisAngle(new T.Vector3(0,1,0),entered?look:-.55);camera.lookAt(camera.position.clone().add(forward.multiplyScalar(20)));lamps.forEach((l,i)=>{let s=1+bass*.8+burst*.4;l.scale.setScalar(s);l.rotation.y=now*.0003+i});glow.emissiveIntensity=.6+bass*3+burst*2;fronds.forEach((f,i)=>f.rotation.z=Math.sin(now*.001+i)*(.025+high*.18));flowers.forEach((f,i)=>f.scale.setScalar(1+burst*.8+Math.sin(now*.001+i)*energy*.4));motes.rotation.y=now*.000003;$('progress').firstElementChild.style.width=((angle%(Math.PI*2))/(Math.PI*2)*100)+'%';Array.from($('bars').children).forEach((b,i)=>b.style.height=(4+(buffer?buffer[i*4]/255:0)*24)+'px');let section=Math.floor((angle%(Math.PI*2))/(Math.PI*2)*3);$('chapter').textContent=['01 / KAMPUNG CANOPY','02 / WOVEN LIGHT','03 / GARDENS OF TOMORROW'][section];$('chapterTitle').textContent=['Where tomorrow takes root.','Follow the sound. Find the glow.','Everything comes around.'][section];renderer.render(scene,camera)}requestAnimationFrame(animate);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
